def _parse() -> dict[str, DecisionSpec]:
    specs: dict[str, DecisionSpec] = {}
    sources = (
        ("v3.3", _V33_LINES),
        ("v3.4", _V34_ADDITIONS),
    )
    for origin, text in sources:
        for line_number, raw in enumerate(text.splitlines(), 1):
            parts = [part.strip() for part in raw.split("|")]
            if len(parts) != 6:
                raise ValueError(
                    f"decision spec {origin} line {line_number} has {len(parts)} fields"
                )
            spec = DecisionSpec(*parts)
            if origin == "v3.3":
                family = spec.source_task.split("/", 1)[0]
                retired = (
                    "-esc-burie-quiet" in spec.source_task
                    or family in {"business_brief_fb", "finance_qa_fb"}
                    or (family == "erpbench" and spec.source_task != "erpbench/2160-hard-17-shared-component-subassemblies-branch-assigned")
                    or (family == "erp_qa_fb" and spec.source_task != "erp_qa_fb/aged-balance-12")
                )
                if retired:
                    continue
            if spec.source_task in specs:
                raise ValueError(f"duplicate decision spec: {spec.source_task}")
            specs[spec.source_task] = spec
    if len(specs) != 100:
        raise ValueError(f"expected 100 decision specs, found {len(specs)}")
    if len({spec.decision_code for spec in specs.values()}) != 100:
        raise ValueError("every task needs a distinct decision code")
    if len({spec.employee_question for spec in specs.values()}) != 100:
        raise ValueError("every task needs a distinct employee question")
    return specs


DECISION_SPECS = _parse()


def decision_spec(source_task: str) -> DecisionSpec:
    try:
        return DECISION_SPECS[source_task]
    except KeyError as error:
        raise KeyError(f"no authored decision spec for {source_task}") from error
